    privacyPolicyTitle: "Politique de Confidentialité",
    privacyPolicyContent: "<b>1. Collecte des données :</b> Nous collectons votre nom, email et numéro de téléphone lors d'une réservation.<br><br><b>2. Utilisation des données :</b> Pour confirmer votre réservation et assurer un service de qualité.<br><br><b>3. Protection des données :</b> Vos données sont stockées en toute sécurité et ne sont jamais partagées avec des tiers à des fins commerciales.<br><br><b>4. Votre Droits :</b> Vous avez le droit d'accéder de rectifier ou de supprimer vos données personnelles. Contactez-nous à restaurantlegandhi@orange.fr.",
