    legalNoticeContent: "Le Gandhi<br>39 Rue de l'Industrie, 31000 Toulouse<br><br><b>Website Host:</b> Vercel Inc.<br><b>Email:</b> restaurantlegandhi@orange.fr<br><b>Phone:</b> +33 5 61 99 21 03<br><br><b>Responsibility:</b> Le Gandhi strives to ensure the accuracy of information on this site but cannot be held responsible for omissions or inaccuracies.<br><br><b>Intellectual Property:</b> All content, including text, images, and logos, is the property of Le Gandhi unless otherwise stated.<br><br><b>Personal Data:</b> We collect only the data necessary for your reservations.",
    privacyPolicyTitle: "Política de Privacidad",
    privacyPolicyContent: "<b>1. Data Collection:</b> We collect your name, email, and phone number when you make a reservation.<br><br><b>2. Data Usage:</b> To confirm your reservation and provide quality service.<br><br><b>3. Data Protection:</b> Your data is securely stored and never shared with third parties for commercial purposes.<br><br><b>4. Your Rights:</b> You have the right to access, rectify, or delete your personal data. Contact us at restaurantlegandhi@orange.fr.",
    cookiePolicyTitle: "Política de Cookies",
    cookiePolicyContent: "<b>1. What are cookies?</b> Small files stored on your computer to improve your experience.<br><br><b>2. Our Use:</b> We use cookies for website analytics and to remember your preferences.<br><br><b>3. Your Choice:</b> You can disable cookies in your browser settings, though some site features may be affected.",
