    aboutMissionP1: "Fondé avec une vision simple mais ambitieuse : offrir à Toulouse une expérience culinaire indienne véritablement authentique. Le Gandhi s'engage à utiliser uniquement les meilleurs ingrédients et les techniques de cuisson traditionnelles.",
