    specTitle: "Unsere indischen Spezialitäten",
    storyLabel: "Unsere Geschichte",
    storyP1: "Das Gandhi ist viel mehr als ein Restaurant; Es ist eine kulinarische Reise ins Herz Indiens. Wir wurden 1991 gegründet und bringen das reiche Erbe der indischen Küche auf die Straßen von Toulouse.",
    storyP2: "Unsere Köche verwenden <span class='highlight'>traditionelle Gewürze, die direkt aus Indien importiert werden</span> und überlieferte Techniken, um eine Explosion authentischen Geschmacks zu garantieren.",
    storyTitle: "Eine Leidenschaft für Authentizität",
    testi1: "Eine Geschmacksexplosion! Ohne Zweifel das beste indische Restaurant in Toulouse. Das Butterhuhn ist ein Traum.",
    testi1Author: "John Dupont",
    testi2: "Authentizität und tadelloser Service. Wir fühlen uns wirklich willkommen. Die Gewürze sind perfekt ausbalanciert.",
    testi2Author: "Marie Laurent",
    testi3: "Parfait pour un dîner romantique. L'ambiance est chaleureuse et les plats sont généreux.",
    testi3Author: "Pierre Bernard",
