    specShawarma: "Особливий Талі",
    specShawarmaDesc: "Індійський талі: золотистий рис, міні-каррі, сочевиця, раїта та домашнє чатні.",
    specTandoori: "Великий Талі",
    specTandooriDesc: "Повне блюдо подається з шафрановим рисом, різними каррі, раїтою та традиційними приправами.",
    specTitle: "Наші страви індійської кухні",
    storyLabel: "Наша історія",
    storyP1: "Gandhi - це набагато більше, ніж ресторан; це кулінарна подорож до серця Індії. Заснована в 1991 році, ми приносимо багату спадщину індійської кухні на вулиці Тулузи.",
    storyP2: "Наші шеф-кухарі використовують <span class='highlight'>традиційні спеції, імпортовані безпосередньо з Індії</span>, і техніку предків, щоб гарантувати вибух автентичного смаку.",
    storyTitle: "Пристрасть до автентичності",
    testi1: "Вибух смаків! Найкращий індійський ресторан у Тулузі без сумніву. За курку з маслом можна померти.",
    testi1Author: "Джон Дюпон",
    testi2: "Автентичність і бездоганне обслуговування. Нас справді вітають. Спеції ідеально збалансовані.",
    testi2Author: "Марі Лоран",
    testi3: "Ідеально підходить для романтичної вечері. Атмосфера тепла, а страви щедрі.",
