    aboutMissionP1: "Osnovan s jednostavnom, ali ambicioznom vizijom: ponuditi Toulouseu istinski autentično indijsko kulinarsko iskustvo. Le Gandhi je predan korištenju samo najboljih sastojaka i tradicionalnih tehnika kuhanja.",
